CREATE TABLE `workflow_build_executions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `plan_id` binary(16) DEFAULT NULL,
  `external_build_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT 'The ID from the build backend for this build',
  `workflow_build_id` bigint NOT NULL COMMENT 'References the workflow build that this execution runs',
  `queued_at` datetime(6) DEFAULT NULL,
  `started_at` datetime(6) DEFAULT NULL,
  `completed_at` datetime(6) DEFAULT NULL,
  `state` int NOT NULL DEFAULT '0' COMMENT 'See WorkflowState for values',
  `was_delayed` tinyint(1) DEFAULT '0',
  `triggering_actor_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `triggering_actor_next_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `attempt` int NOT NULL DEFAULT '1',
  `webhook_delivery_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `reporting_metadata` json DEFAULT NULL COMMENT 'See WorkflowMetadata for values',
  `infrastructure_failed` tinyint(1) DEFAULT '0',
  `azp_completed_at` datetime(6) DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `backend` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `by_plan_id` (`plan_id`),
  UNIQUE KEY `by_workflow_build_id_webhook_delivery_id` (`workflow_build_id`,`webhook_delivery_id`),
  KEY `by_started_at` (`started_at`),
  KEY `by_queued_at` (`queued_at`),
  KEY `by_completed_at_queued_at` (`completed_at`,`queued_at`),
  KEY `by_workflow_build_id_state` (`workflow_build_id`,`state`),
  KEY `by_workflow_build_id_completed_at_state` (`workflow_build_id`,`completed_at`,`state`),
  KEY `by_created_at` (`created_at`),
  KEY `by_triggering_actor_id_state_queued_at` (`triggering_actor_id`,`state`,`queued_at`),
  KEY `by_triggering_actor_next_id_state_queued_at` (`triggering_actor_next_id`,`state`,`queued_at`),
  KEY `by_state_completed_at_created_at` (`state`,`completed_at`,`created_at`),
  KEY `by_backend_state_completed_at_created_at` (`backend`,`state`,`completed_at`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
